<script>
 import { onMount,tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { freeformSession,freeformDocument,freeformAvailability } from './freeform-state.js';
 import { freeformMenus } from './freeform-menus.js';
 import { createFreeformNativeView } from './freeform-native-view.js';
 import { freeformPinGraph,freeformConnector,freeformFontFamily } from './freeform-engine.js';
 import { loadAvailableFonts } from './font-book-fonts.js';
 import './freeform.css';
 let {state: freeformState,profile,window:actualWindow=null,windowId=actualWindow?.id,controller,execute=null,oncommand=null,registerView=null,available=true,active=true,controls={}}=$props();
 let root=$state(null),viewport=$state(null),message=$state(''),gesture=$state(null),saveName=$state('Untitled'),format=$state('png');
 let originalState,originalProfile,originalWindow,originalController,originalSession,originalId,retired=false,mounted=$state(false);
 const session=$derived(freeformSession(freeformState,windowId)),doc=$derived(freeformDocument(freeformState,session?.documentId)),cap=$derived(freeformAvailability(profile)),menus=$derived(freeformMenus(profile,freeformState,windowId)),objects=$derived(doc?.content.objects??[]),selected=$derived(objects.filter(o=>session?.selectedIds.includes(o.id))),first=$derived(selected[0]),fonts=$derived(controller?.fonts?.()??[]),photos=$derived(controller?.photos?.()??[]);
 function owned(){return !retired&&root?.isConnected===true&&freeformState===originalState&&profile===originalProfile&&actualWindow===originalWindow&&windowId===originalId&&controller===originalController&&session===originalSession;}
 async function run(name,payload={}){if(!owned()||!available||!active)return;const runner=oncommand??execute,r=runner?await runner(`freeform.${name}`,{windowId},payload):await controller?.handlers?.[`freeform.${name}`]?.({windowId},payload);if(owned())message=r?.status==='applied'?'':r?.error?.message??'The original board operation is unavailable.';return r;}
 const update=values=>run('object.update',{values});
 function point(e){const r=viewport.getBoundingClientRect();return {x:Math.max(-16000,Math.min(16000,(e.clientX-r.left-session.pan.x)/session.zoom)),y:Math.max(-16000,Math.min(16000,(e.clientY-r.top-session.pan.y)/session.zoom))};}
 function style(o){const moving=gesture?.kind==='move'&&gesture.ids.includes(o.id),dx=moving?gesture.end.x-gesture.start.x:0,dy=moving?gesture.end.y-gesture.start.y:0;return `left:${o.x+dx}px;top:${o.y+dy}px;width:${o.width}px;height:${o.height}px;--object-fill:${o.fill};--object-ink:${o.stroke};font-size:${o.size}px;font-family:${freeformFontFamily(o.font,controller?.fontGraph?.(),controller?.getFile)};font-weight:${o.bold?700:400};text-align:${o.align};`;}
 function validGesture(g){return owned()&&available&&active&&doc===g.doc&&g.pin()&&g.objects===doc.content.objects&&controller?.sceneTime?.()===g.time;}
 async function begin(e,o=null){if(!owned()||!available||!active||!doc||session.panel!=='none'||e.button!==0||e.target.closest('textarea,input,audio,video,select,button'))return;e.preventDefault();viewport.setPointerCapture(e.pointerId);const start=point(e),tool=session.tool,kind=tool==='pan'?'pan':tool==='pen'?'pen':tool!=='select'?'add':o?'move':'marquee';gesture={kind,start,end:kind==='pan'?{x:0,y:0}:start,client:{x:e.clientX,y:e.clientY},pan:{...session.pan},pointer:e.pointerId,doc,objects:doc.content.objects,pin:freeformPinGraph(doc.content),time:controller?.sceneTime?.(),ids:[],points:[start],tool,ready:kind!=='move'};const g=gesture;
 if(kind==='move'){const ids=e.shiftKey?(session.selectedIds.includes(o.id)?session.selectedIds.filter(id=>id!==o.id):[...session.selectedIds,o.id]):session.selectedIds.includes(o.id)?session.selectedIds:[o.id];const r=await run('selection',{ids});if(gesture!==g||!validGesture(g)||r?.status!=='applied'){if(gesture===g)gesture=null;return;}g.ids=[...session.selectedIds];g.ready=true;}
 }
 function move(e){const g=gesture;if(!g||e.pointerId!==g.pointer)return;if(!validGesture(g)){gesture=null;return;}g.end=point(e);if(g.kind==='pan'){g.end={x:e.clientX-g.client.x,y:e.clientY-g.client.y};}if(g.kind==='pen'&&g.points.length<4096){const last=g.points[g.points.length-1];if(Math.hypot(g.end.x-last.x,g.end.y-last.y)>1/session.zoom)g.points.push(g.end);}}
 async function end(e){const g=gesture;if(!g||g.pointer!==e.pointerId)return;gesture=null;if(!validGesture(g)||!g.ready)return;const dx=g.end.x-g.start.x,dy=g.end.y-g.start.y;if(g.kind==='pan'){await run('view',{pan:{x:Math.max(-16000,Math.min(16000,g.pan.x+g.end.x)),y:Math.max(-16000,Math.min(16000,g.pan.y+g.end.y))}});}else if(g.kind==='move'){if(dx||dy)await run('selection.move',{dx,dy});}else if(g.kind==='pen'){if(g.points.length>1)await run('stroke.add',{points:g.points});}else if(g.kind==='marquee'){const left=Math.min(g.start.x,g.end.x),right=Math.max(g.start.x,g.end.x),top=Math.min(g.start.y,g.end.y),bottom=Math.max(g.start.y,g.end.y);await run('selection',{ids:Math.abs(dx)+Math.abs(dy)<4?[]:objects.filter(o=>o.type!=='connector'&&o.x<=right&&o.x+o.width>=left&&o.y<=bottom&&o.y+o.height>=top).map(o=>o.id)});}else{const isShape=['rect','ellipse','diamond','triangle'].includes(g.tool);await run('object.add',{type:isShape?'shape':g.tool,...(isShape?{shape:g.tool}:{}),x:Math.min(g.start.x,g.end.x),y:Math.min(g.start.y,g.end.y),width:Math.abs(dx)>5?Math.abs(dx):200,height:Math.abs(dy)>5?Math.abs(dy):g.tool==='text'?80:160});}}
 function wheel(e){if(!doc||!owned()||!active||!available)return;e.preventDefault();if(e.ctrlKey||e.metaKey){const zoom=Math.max(.1,Math.min(4,session.zoom*Math.exp(-e.deltaY*.002))),r=viewport.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;run('view',{zoom,pan:{x:Math.max(-16000,Math.min(16000,x-(x-session.pan.x)*zoom/session.zoom)),y:Math.max(-16000,Math.min(16000,y-(y-session.pan.y)*zoom/session.zoom))}});}else run('view',{pan:{x:Math.max(-16000,Math.min(16000,session.pan.x-e.deltaX)),y:Math.max(-16000,Math.min(16000,session.pan.y-e.deltaY))}});}
 function key(e){if(!owned()||!available||!active)return;const typing=e.target.closest('input,textarea,select')||e.target.isContentEditable,k=e.key.toLowerCase();if((e.metaKey||e.ctrlKey)&&!e.altKey){const name=k==='s'?'save':k==='o'?'open':!typing&&k==='z'?(e.shiftKey?'redo':'undo'):!typing&&k==='c'?(e.shiftKey?'copy.image':'copy'):!typing&&k==='v'?'paste':!typing&&k==='d'?'selection.duplicate':null;if(name){e.preventDefault();if(k==='s'&&e.shiftKey)run('panel',{panel:'save'});else run(name);}if(!typing&&k==='a'){e.preventDefault();run('selection',{ids:objects.map(o=>o.id)});}}if(e.key==='Escape'){gesture=null;run('panel',{panel:'none'});return;}if(typing)return;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();run('selection.delete');}if(selected.length&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=e.shiftKey?10:1;run('selection.move',{dx:e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0,dy:e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0});}}
 async function menuItem(item){if(!item.enabled)return;const r=await run('menu',{menuId:null});if(r?.status==='applied'&&owned())await run(item.command.slice(9),item.payload);}
 $effect(()=>{if(!mounted)return;const graph=controller?.fontGraph?.(),signature=JSON.stringify(graph),pin=freeformPinGraph(graph),original=controller,time=controller?.sceneTime?.();let cancelled=false,loaded=null;const guard=()=>!cancelled&&owned()&&controller===original&&controller.sceneTime()===time&&controller.fontGraph()===graph&&pin()&&JSON.stringify(graph)===signature;if(graph)loadAvailableFonts(graph,{getFile:controller.getFile,guard}).then(result=>{if(guard())loaded=result;else result.dispose();}).catch(error=>{if(guard())message=error.message;});return()=>{cancelled=true;loaded?.dispose();};});
 onMount(()=>{originalState=freeformState;originalProfile=profile;originalWindow=actualWindow;originalController=controller;originalSession=session;originalId=windowId;mounted=true;const view=createFreeformNativeView({getRoot:()=>root,getState:()=>freeformState,getSession:()=>session,getProfile:()=>profile,getWindow:()=>actualWindow,getController:()=>controller,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>freeformMenus(profile,freeformState,windowId)});registerView?.(windowId,view);return()=>{retired=true;view.destroy();registerView?.(originalId,null,view);};});
</script>
<section bind:this={root} class="freeform-app" class:legacy={cap.legacy} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-freeform-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="-1" onkeydown={key}>
 <header class="freeform-titlebar">
  {#if !cap.windows}<WindowControls active={active} onclose={()=>run('close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
  <strong>{doc?.content.title??cap.label}</strong><span>{doc?.dirty?'Edited':doc?.fileId?'Portable Board':'On My Computer'}</span>
  {#if cap.local}<small>Local counterpart · not an installed Apple app</small>{/if}
  {#if cap.windows}<button aria-label="Minimize" disabled={typeof controls.onminimize!=='function'} onclick={controls.onminimize}>−</button><button aria-label="Maximize or restore" disabled={typeof controls.onzoom!=='function'} onclick={controls.onzoom}>□</button><button aria-label="Close" onclick={()=>run('close')}>×</button>{/if}
 </header>
 {#if cap.local}<nav class="freeform-menubar" aria-label="Application menus">{#each menus as menu}<button data-freeform-control={`menu:${menu.id}`} onclick={()=>run('menu',{menuId:session?.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if session?.menu}<div class="freeform-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menuItem(item)} data-freeform-control={`menuitem:${item.id}`}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <div class="freeform-toolbar" inert={!available||!active||session?.panel!=='none'}>
  <button data-freeform-control="sidebar" aria-label="Show boards sidebar" class:selected={session?.sidebar} onclick={()=>run('view',{sidebar:!session?.sidebar})}>▤</button>
  <button data-freeform-control="new" onclick={()=>run('new')}>＋ New Board</button><button data-freeform-control="open" onclick={()=>run('open')}>Open…</button>
  <span class="freeform-spacer"></span>
  {#each [{id:'select',icon:'↖',label:'Select'},{id:'pan',icon:'✋',label:'Pan'},{id:'pen',icon:'〰',label:'Pen'},{id:'sticky',icon:'▨',label:'Note'},{id:'rect',icon:'□',label:'Shape'},{id:'text',icon:'T',label:'Text'}] as tool}<button data-freeform-control={`tool:${tool.id}`} disabled={!doc} class:selected={session?.tool===tool.id} onclick={()=>run('view',{tool:tool.id})}><b>{tool.icon}</b><small>{tool.label}</small></button>{/each}
  <button data-freeform-control="media" disabled={!doc} onclick={()=>run('media.insert')}><b>▧</b><small>Media</small></button>
  <span class="freeform-spacer"></span><button data-freeform-control="share" disabled={!doc} onclick={()=>run('share')}>↑ Share Copy</button><button data-freeform-control="inspector" class:selected={session?.inspector} onclick={()=>run('view',{inspector:!session?.inspector})}>☷</button>
 </div>
 <div class="freeform-workspace" inert={!available||!active||session?.panel!=='none'}>
  {#if session?.sidebar}<aside class="freeform-sidebar" data-freeform-area="boards"><h2>On My Computer</h2><p class="freeform-sidebar-caption">All Boards <span>{freeformState.documents.length}</span></p>{#each freeformState.documents as d (d.id)}<button data-freeform-control={`board:${d.id}`} class:selected={doc===d} onclick={()=>run('document.select',{documentId:d.id})}><span class="freeform-board-thumb">{#each d.content.objects.slice(0,12) as o}<i style={`left:${10+Math.abs(o.x)%60}%;top:${10+Math.abs(o.y)%60}%;background:${o.fill};`}></i>{/each}</span><strong>{d.content.title}</strong><small>{d.dirty?'Edited':d.fileId?'Saved .jboard':'Unsaved Board'} · {d.content.objects.length} items</small></button>{/each}<button data-freeform-control="new-sidebar" onclick={()=>run('new')}>＋ New Board</button></aside>{/if}
  <main bind:this={viewport} class="freeform-viewport" class:pan={session?.tool==='pan'} class:draw={session?.tool==='pen'} onpointerdown={e=>begin(e)} onpointermove={move} onpointerup={end} onpointercancel={()=>gesture=null} onwheel={wheel} role="group" aria-label="Editable vector board" tabindex="0" data-freeform-control="canvas" style={`background-color:${doc?.content.background??'#fff'};--dot-size:${20*(session?.zoom??1)}px;--pan-x:${session?.pan.x??0}px;--pan-y:${session?.pan.y??0}px;`}>
  {#if doc}<div class="freeform-stage" style={`transform:translate(${session.pan.x+(gesture?.kind==='pan'?gesture.end.x:0)}px,${session.pan.y+(gesture?.kind==='pan'?gesture.end.y:0)}px) scale(${session.zoom});`}>
   <svg class="freeform-lines" aria-label="Vector strokes and connectors"><defs><marker id={`arrow-${windowId}`} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="context-stroke"/></marker></defs>
    {#each objects.filter(o=>o.type==='connector') as o (o.id)}{@const c=freeformConnector(o,objects)}{#if c}<line x1={c.x1} y1={c.y1} x2={c.x2} y2={c.y2} stroke={session.selectedIds.includes(o.id)?'#007aff':o.stroke} stroke-width={o.lineWidth} marker-end={`url(#arrow-${windowId})`} class="freeform-connector" data-freeform-object={o.id} role="button" tabindex="0" aria-label="Select connector" onpointerdown={e=>{e.stopPropagation();run('selection',{ids:[o.id]});}} onkeydown={e=>{if(e.key==='Enter')run('selection',{ids:[o.id]});}}/>{/if}{/each}
    {#if gesture?.kind==='pen'}<polyline points={gesture.points.map(p=>`${p.x},${p.y}`).join(' ')} fill="none" stroke="#3972b7" stroke-width="2"/>{/if}
   </svg>
   {#each objects.filter(o=>o.type!=='connector') as o (o.id)}<div class="freeform-object" class:selected={session.selectedIds.includes(o.id)} class:sticky={o.type==='sticky'} class:text={o.type==='text'} style={style(o)} data-freeform-object={o.id} data-freeform-control={`object:${o.id}`} role="group" tabindex="0" aria-label={`${o.type}: ${o.text||o.shape}`} onkeydown={e=>{if(e.currentTarget===e.target&&e.key==='Enter'){e.stopPropagation();run('selection',{ids:e.shiftKey?[...new Set([...session.selectedIds,o.id])]:[o.id]});}}} onpointerdown={e=>{e.stopPropagation();begin(e,o);}}>
    {#if o.type==='shape'}<svg width="100%" height="100%" viewBox={`0 0 ${o.width} ${o.height}`} aria-hidden="true">{#if o.shape==='ellipse'}<ellipse cx={o.width/2} cy={o.height/2} rx={Math.max(1,o.width/2-o.lineWidth)} ry={Math.max(1,o.height/2-o.lineWidth)} fill={o.fill} stroke={o.stroke} stroke-width={o.lineWidth}/>{:else if o.shape==='diamond'}<polygon points={`${o.width/2},2 ${o.width-2},${o.height/2} ${o.width/2},${o.height-2} 2,${o.height/2}`} fill={o.fill} stroke={o.stroke} stroke-width={o.lineWidth}/>{:else if o.shape==='triangle'}<polygon points={`${o.width/2},2 ${o.width-2},${o.height-2} 2,${o.height-2}`} fill={o.fill} stroke={o.stroke} stroke-width={o.lineWidth}/>{:else}<rect x={o.lineWidth/2} y={o.lineWidth/2} width={Math.max(1,o.width-o.lineWidth)} height={Math.max(1,o.height-o.lineWidth)} rx="8" fill={o.fill} stroke={o.stroke} stroke-width={o.lineWidth}/>{/if}</svg><span class="freeform-shape-text">{o.text}</span>
    {:else if o.type==='text'||o.type==='sticky'}{#if session.selectedIds.length===1&&session.selectedIds[0]===o.id}<textarea data-freeform-control={`text:${o.id}`} aria-label={`Edit ${o.type}`} value={o.text} maxlength="32768" onchange={e=>update({text:e.currentTarget.value})}></textarea>{:else}<span class="freeform-note-text">{o.text}</span>{/if}
    {:else if o.type==='image'}<img draggable="false" src={o.content} alt={o.text||'Imported board image'}/>
    {:else if o.type==='stroke'}<svg width="100%" height="100%" viewBox={`0 0 ${o.width} ${o.height}`} aria-hidden="true"><polyline points={o.points.map(p=>`${p.x},${p.y}`).join(' ')} fill="none" stroke={o.stroke} stroke-width={o.lineWidth} stroke-linecap="round" stroke-linejoin="round"/></svg>
    {:else if o.type==='audio'}<div class="freeform-media-label">♫ {o.text}</div><audio controls src={o.content} data-freeform-media={o.id} data-freeform-control={`media:${o.id}`} preload="metadata"></audio>
    {:else}<video controls src={o.content} data-freeform-media={o.id} data-freeform-control={`media:${o.id}`} preload="metadata"></video><div class="freeform-media-label">▶ {o.text}</div>{/if}
    {#if o.groupId}<span class="freeform-group-label">Grouped</span>{/if}
   </div>{/each}
   {#if gesture?.kind==='marquee'||gesture?.kind==='add'}<div class="freeform-marquee" style={`left:${Math.min(gesture.start.x,gesture.end.x)}px;top:${Math.min(gesture.start.y,gesture.end.y)}px;width:${Math.abs(gesture.end.x-gesture.start.x)}px;height:${Math.abs(gesture.end.y-gesture.start.y)}px;`}></div>{/if}
   {#if !objects.length}<div class="freeform-canvas-hint"><h2>A little space for big ideas.</h2><p>Add a sticky note, draw a connection, or bring in a real image.</p><span>Drag empty space to select · Scroll to pan · ⌘/Ctrl-scroll to zoom</span></div>{/if}
  </div>{:else}<div class="freeform-empty"><div class="freeform-empty-icon">▨</div><h1>Bring your ideas together</h1><p>Shapes, notes, drawings and real media on a flexible board.</p><button data-freeform-control="create-board" onclick={()=>run('new')}>Create a Board</button><button data-freeform-control="open-board" onclick={()=>run('open')}>Open .jboard…</button><small>{cap.disclosure}</small></div>{/if}
  </main>
  {#if session?.inspector&&doc}<aside class="freeform-inspector" data-freeform-area="inspector"><h2>{selected.length?`${selected.length} Selected`:'Board'}</h2>
   {#if first}<label>Text<textarea aria-label="Object text" data-freeform-control="inspector:text" value={first.text} maxlength="32768" onchange={e=>update({text:e.currentTarget.value})}></textarea></label><div class="freeform-fields">{#each ['x','y','width','height'] as field}<label>{field}<input data-freeform-control={`inspector:${field}`} type="number" value={first[field]} min={field==='width'||field==='height'?1:-16000} max={field==='width'||field==='height'?8192:16000} onchange={e=>update({[field]:Number(e.currentTarget.value)})}/></label>{/each}</div>
   <label>Fill<input type="color" data-freeform-control="fill" value={first.fill} onchange={e=>update({fill:e.currentTarget.value})}/></label><label>Line & Text<input type="color" data-freeform-control="stroke" value={first.stroke} onchange={e=>update({stroke:e.currentTarget.value})}/></label><label>Line Width<input type="number" min="0.25" max="32" step="0.25" value={first.lineWidth} onchange={e=>update({lineWidth:Number(e.currentTarget.value)})}/></label>
   {#if first.type==='shape'}<label>Shape<select value={first.shape} onchange={e=>update({shape:e.currentTarget.value})}>{#each ['rect','ellipse','diamond','triangle'] as shape}<option>{shape}</option>{/each}</select></label>{/if}
   <label>Font · canonical FontGraph<select data-freeform-control="font" value={first.font} onchange={e=>update({font:e.currentTarget.value})}>{#if !fonts.some(f=>f.family===first.font)}<option value={first.font}>{first.font} (system fallback)</option>{/if}{#each [...new Set(fonts.map(f=>f.family))] as family}<option value={family}>{family}</option>{/each}</select></label><label>Text Size<input type="number" min="4" max="144" value={first.size} onchange={e=>update({size:Number(e.currentTarget.value)})}/></label><div class="freeform-actions"><button onclick={()=>update({bold:!first.bold})} class:selected={first.bold}>B</button>{#each ['left','center','right'] as align}<button class:selected={first.align===align} onclick={()=>update({align})}>{align}</button>{/each}</div>
   <h3>Arrange</h3><div class="freeform-actions">{#each ['left','center','right','top','middle','bottom'] as direction}<button disabled={selected.length<2} onclick={()=>run('selection.align',{direction})}>{direction}</button>{/each}</div><div class="freeform-actions"><button disabled={selected.length<2} onclick={()=>run('selection.group')}>Group</button><button onclick={()=>run('selection.ungroup')}>Ungroup</button><button disabled={selected.length!==2} onclick={()=>run('connector.add',{from:selected[0].id,to:selected[1].id})}>Connect</button><button onclick={()=>run('selection.duplicate')}>Duplicate</button><button onclick={()=>run('selection.delete')}>Delete</button></div>
   {:else}<label>Board Name<input data-freeform-control="title" value={doc.content.title} maxlength="256" onchange={e=>run('document.rename',{title:e.currentTarget.value})}/></label><p>Select one or more objects to edit their style and arrangement. Shift-click extends selection.</p><button data-freeform-control="photos" onclick={()=>run('panel',{panel:'photos'})}>Choose from Photos…</button><button data-freeform-control="new-window" onclick={()=>run('window.new')}>New Window of This Board</button>{/if}
   <hr/><button data-freeform-control="save" onclick={()=>run('save')}>Save .jboard</button><button data-freeform-control="save-as" onclick={()=>{saveName=doc.content.title;run('panel',{panel:'save'});}}>Save As…</button><button data-freeform-control="export" onclick={()=>{saveName=doc.content.title;run('panel',{panel:'export'});}}>Export PNG / PDF…</button><button data-freeform-control="copy-image" onclick={()=>run('copy.image')}>Copy Board as Image</button><button data-freeform-control="print" onclick={()=>run('print')}>Print…</button>
  </aside>{/if}
 </div>
 <footer class="freeform-status"><span>{message||`${objects.length} items${selected.length?' · '+selected.length+' selected':''}${cap.local?' · Explicit local counterpart':''}`}</span><button disabled={!doc} onclick={()=>run('view',{zoom:Math.max(.1,(session?.zoom??1)/1.25)})} aria-label="Zoom out">−</button><select data-freeform-control="zoom" aria-label="Board zoom" value={session?.zoom??1} onchange={e=>run('view',{zoom:Number(e.currentTarget.value)})}>{#each [.1,.25,.5,.75,1,1.5,2,3,4] as zoom}<option value={zoom}>{Math.round(zoom*100)}%</option>{/each}{#if session&&!([.1,.25,.5,.75,1,1.5,2,3,4].includes(session.zoom))}<option value={session.zoom}>{Math.round(session.zoom*100)}%</option>{/if}</select><button disabled={!doc} onclick={()=>run('view',{zoom:Math.min(4,(session?.zoom??1)*1.25)})} aria-label="Zoom in">＋</button></footer>
 {#if session?.panel!=='none'&&session}<div class="freeform-sheet-backdrop"><section class="freeform-sheet" role="dialog" aria-modal="true" aria-label={session.panel==='close'?'Save board changes':session.panel==='help'?'Freeform availability and help':session.panel==='photos'?'Photos source picker':'Board output'}>
  {#if session.panel==='close'}<h2>Save changes to “{doc?.content.title}”?</h2><p>This board is shared by every window showing it. Discard restores the saved board in those windows too.</p><div class="freeform-sheet-actions"><button data-freeform-control="close:cancel" onclick={()=>run('close',{decision:'cancel'})}>Cancel</button><button data-freeform-control="close:discard" onclick={()=>run('close',{decision:'discard'})}>Discard Changes</button><button class="primary" data-freeform-control="close:save" onclick={()=>run('close',{decision:'save'})}>Save</button></div>
  {:else if session.panel==='help'}<h2>{cap.label}</h2><p>{cap.disclosure}</p><p>Click or drag objects to select and move. Shift-click adds to selection. Drag empty space for a selection rectangle. Select two objects and choose Connect. Scroll pans; Ctrl/⌘-scroll zooms. Pen is an explicitly local drawing extension. Audio and video retain genuine embedded bytes in .jboard; static output uses labeled attachment cards.</p><p>Photos appears only with explicit OS privacy permission. Fonts are read directly from the canonical FontGraph.</p><button class="primary" data-freeform-control="help:done" onclick={()=>run('panel',{panel:'none'})}>Done</button>
  {:else if session.panel==='photos'}<h2>Photos Library</h2><p>Read-only selection from the actual canonical Photos library. Inserting embeds a copy; it never edits Photos.</p>{#if photos.length}<div class="freeform-photo-grid">{#each photos as photo (photo.id)}<button data-freeform-control={`photo:${photo.id}`} onclick={()=>run('photo.insert',{photoId:photo.id})}><img src={photo.content} alt={photo.title}/><span>{photo.title}</span></button>{/each}</div>{:else}<p>No visible photos available. An explicit allowed Photos permission for this app is required. You can independently choose a real File with Media.</p>{/if}<button data-freeform-control="photos:cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button>
  {:else}<h2>{session.panel==='save'?'Save Portable Board':'Export Board'}</h2><label>Name<input data-freeform-control="output:name" bind:value={saveName} maxlength="240"/></label>{#if session.panel==='export'}<label>Format<select data-freeform-control="output:format" bind:value={format}><option value="png">PNG image</option><option value="pdf">PDF document</option><option value="jboard">Custom portable board (.jboard)</option></select></label><p>Images and PDF contain the actual rendered board. Audio/video appear as labeled attachment cards; use .jboard for playable embedded media.</p>{:else}<p>.jboard is the honest custom Jester portable format, not Apple Freeform’s proprietary document format.</p>{/if}<div class="freeform-sheet-actions"><button data-freeform-control="output:cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button class="primary" data-freeform-control="output:save" onclick={()=>session.panel==='save'?run('save',{saveAs:true,name:saveName}):run('export',{format,name:saveName})}>{session.panel==='save'?'Save':'Export'}</button></div>{/if}
  {#if message}<p class="freeform-error" role="alert">{message}</p>{/if}
 </section></div>{/if}
</section>
